import{_ as o,C as a,o as h,c as l,aj as d,E as r}from"./framework.js";const u=JSON.parse('{"title":"开发者模式 | Product | Documentation","description":"开发者模式适合连续编辑多个站点资源。它不会替代 CMS 开发菜单：CMS 更适合单个资源的结构化表单和列表管理；开发者模式更适合在页面、布局、视图、脚本、样式、Code 之间来回切换。","frontmatter":{"title":"开发者模式 | Product | Documentation","description":"开发者模式适合连续编辑多个站点资源。它不会替代 CMS 开发菜单：CMS 更适合单个资源的结构化表单和列表管理；开发者模式更适合在页面、布局、视图、脚本、样式、Code 之间来回切换。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/product/developer-mode.html"}]]},"headers":[],"relativePath":"zh/product/developer-mode.md","filePath":"product/developer-mode.md","lastUpdated":1781002819000}'),c={name:"zh/product/developer-mode.md"};function i(n,t,b,s,p,_){const e=a("DocImage");return h(),l("div",null,[t[0]||(t[0]=d('<h1 id="开发者模式" tabindex="-1">开发者模式 <a class="header-anchor" href="#开发者模式" aria-label="Permalink to &quot;开发者模式&quot;">​</a></h1><blockquote><p>在站点后台中打开类 VS Code 的开发工作台，同时查看、编辑、搜索和调试多个站点资源。</p></blockquote><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>顶部入口</td><td>进入站点后台后，点击顶部 <strong>开发者模式</strong> 图标</td></tr><tr><td>深链</td><td><code>/_Admin/dev-mode?SiteId={站点GUID}</code></td></tr><tr><td>指定面板</td><td><code>/_Admin/dev-mode?SiteId={站点GUID}&amp;activity={面板名}</code></td></tr><tr><td>前端路由</td><td><code>/dev-mode</code></td></tr><tr><td>页面层级</td><td>站点级页面，必须带 <code>SiteId</code></td></tr></tbody></table><p>开发者模式适合连续编辑多个站点资源。它不会替代 CMS 开发菜单：CMS 更适合单个资源的结构化表单和列表管理；开发者模式更适合在页面、布局、视图、脚本、样式、Code 之间来回切换。</p>',5)),r(e,{src:"/product/developer-mode/developer-mode-overview.png",alt:"开发者模式概览：左侧活动栏、资源树和编辑工作区",width:"1120"}),t[1]||(t[1]=d('<h2 id="权限与可见面板" tabindex="-1">权限与可见面板 <a class="header-anchor" href="#权限与可见面板" aria-label="Permalink to &quot;权限与可见面板&quot;">​</a></h2><p>开发者模式会按当前用户的站点权限显示左侧面板。没有对应权限的面板不会出现在活动栏中。</p><table tabindex="0"><thead><tr><th>面板</th><th>权限来源</th><th>主要用途</th></tr></thead><tbody><tr><td>页面</td><td><code>pages</code></td><td>打开普通页面、富文本页面和设计页面</td></tr><tr><td>视图</td><td><code>view</code></td><td>编辑 View 组件</td></tr><tr><td>布局</td><td><code>layout</code></td><td>编辑 Layout</td></tr><tr><td>样式</td><td><code>style</code></td><td>编辑内联样式、外部样式和样式组</td></tr><tr><td>脚本</td><td><code>script</code></td><td>编辑内联脚本、外部脚本和脚本组</td></tr><tr><td>Code</td><td><code>code</code></td><td>编辑 API、CodeBlock、PageScript 等代码资源</td></tr><tr><td>菜单</td><td><code>menu</code></td><td>查看和打开菜单资源</td></tr><tr><td>表单</td><td><code>form</code></td><td>编辑表单资源</td></tr><tr><td>搜索</td><td><code>code</code></td><td>跨站点资源搜索代码内容</td></tr><tr><td>调试</td><td><code>code · debug</code></td><td>打开可调试代码并进入调试面板</td></tr><tr><td>模块</td><td><code>module</code></td><td>查看模块资源，或从模块编辑状态返回普通开发者模式</td></tr><tr><td>设置</td><td><code>site · edit</code></td><td>点击左下角齿轮后，以标签页形式打开站点设置</td></tr></tbody></table><p>如果用户只有部分资源权限，开发者模式会自动裁剪工作区。排查“为什么看不到某个面板”时，先检查角色权限，而不是路由地址。</p><h2 id="工作区结构" tabindex="-1">工作区结构 <a class="header-anchor" href="#工作区结构" aria-label="Permalink to &quot;工作区结构&quot;">​</a></h2><p>开发者模式主要分为三层：</p><table tabindex="0"><thead><tr><th>区域</th><th>怎么用</th></tr></thead><tbody><tr><td>左侧活动栏</td><td>点击图标切换资源类型，例如页面、视图、布局、样式、脚本、Code、搜索、调试</td></tr><tr><td>资源面板</td><td>展示当前资源类型的文件树或列表；顶部可用文件名搜索过滤当前面板</td></tr><tr><td>标签页和编辑区</td><td>点击资源后打开标签页；在编辑区修改内容、保存、刷新或预览</td></tr></tbody></table><p>左侧面板标题右侧通常有两个常用按钮：</p><table tabindex="0"><thead><tr><th>按钮</th><th>说明</th></tr></thead><tbody><tr><td>刷新</td><td>重新加载当前面板的资源列表</td></tr><tr><td>更多</td><td>跳转到对应的 CMS 开发菜单列表页，例如页面列表、布局列表、脚本列表</td></tr></tbody></table><p>底部齿轮按钮会打开站点设置标签页。它使用站点级设置组件，适合临时改一些站点基础配置；完整的站点设置操作仍建议回到 <a href="/kb-docs/zh/cms/settings/">CMS：站点设置</a>。</p><h2 id="打开、编辑和保存资源" tabindex="-1">打开、编辑和保存资源 <a class="header-anchor" href="#打开、编辑和保存资源" aria-label="Permalink to &quot;打开、编辑和保存资源&quot;">​</a></h2><p>点击资源面板中的文件名，资源会在右侧打开一个标签页。再次点击同一个资源不会重复打开标签，而是切回已有标签。</p>',12)),r(e,{src:"/product/developer-mode/opened-resource.png",alt:"开发者模式打开资源后：标签页、保存按钮和代码编辑区",width:"1120"}),t[2]||(t[2]=d('<table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td>打开资源</td><td>在左侧资源面板点击文件名</td></tr><tr><td>切换标签</td><td>点击顶部标签页；标签很多时可横向滚动</td></tr><tr><td>拖动排序</td><td>拖动标签页可调整顺序</td></tr><tr><td>保存</td><td>点击标签页右侧的保存按钮，或使用系统绑定的保存快捷键</td></tr><tr><td>刷新</td><td>重新读取当前资源内容；有未保存修改时先确认</td></tr><tr><td>预览</td><td>页面、视图、布局、脚本、样式、API 等支持预览的资源会显示预览按钮</td></tr><tr><td>关闭</td><td>点击标签页关闭图标；未保存时会弹出确认</td></tr></tbody></table><p>标签左侧出现小圆点表示当前内容已修改但尚未保存。离开开发者模式、切换站点或批量关闭标签时，如果存在未保存内容，界面会提示确认。</p><h2 id="标签页右键菜单" tabindex="-1">标签页右键菜单 <a class="header-anchor" href="#标签页右键菜单" aria-label="Permalink to &quot;标签页右键菜单&quot;">​</a></h2><p>在标签页上点击右键，会打开标签管理菜单。</p><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td>添加代码引用</td><td>对支持的资源，把当前编辑器内容作为代码引用加入 AI 全局聊天</td></tr><tr><td>关闭</td><td>关闭当前标签</td></tr><tr><td>关闭右侧</td><td>关闭当前标签右侧的所有标签</td></tr><tr><td>关闭其他</td><td>只保留当前标签</td></tr><tr><td>关闭已保存</td><td>关闭所有没有未保存修改的标签</td></tr><tr><td>关闭全部</td><td>关闭所有标签；存在未保存修改时会先确认</td></tr></tbody></table><p>“添加代码引用”主要用于让 AI 助手理解当前资源上下文。它不会自动改代码，只是把当前标签内容送到右下角 AI 对话侧边栏中作为引用。</p><h2 id="搜索" tabindex="-1">搜索 <a class="header-anchor" href="#搜索" aria-label="Permalink to &quot;搜索&quot;">​</a></h2><p>开发者模式有两种搜索入口，使用场景不同。</p>',8)),r(e,{src:"/product/developer-mode/code-search.png",alt:"开发者模式全局代码搜索：关键字、大小写、正则和命中行",width:"1120"}),t[3]||(t[3]=d('<table tabindex="0"><thead><tr><th>搜索方式</th><th>入口</th><th>适合什么</th></tr></thead><tbody><tr><td>当前面板文件名搜索</td><td>在资源面板中按 <code>Ctrl + F</code>，或点击资源面板顶部搜索框</td><td>文件很多时快速过滤当前类型的资源名称</td></tr><tr><td>全局代码搜索</td><td>左侧活动栏 <strong>搜索</strong> 面板</td><td>在页面、布局、视图、脚本、样式、Code 等资源内容中查找关键字</td></tr></tbody></table><p>全局代码搜索面板包含三个关键控件：</p><table tabindex="0"><thead><tr><th>控件</th><th>说明</th></tr></thead><tbody><tr><td>关键字输入框</td><td>输入后自动搜索</td></tr><tr><td><code>Aa</code></td><td>切换大小写匹配</td></tr><tr><td><code>.*</code></td><td>切换正则表达式搜索；正则无效时不会提交搜索</td></tr></tbody></table><p>搜索结果按资源分组展示命中行。点击资源名会打开资源并跳到开头；点击某一行命中，会打开资源并跳到对应行。</p><h2 id="调试" tabindex="-1">调试 <a class="header-anchor" href="#调试" aria-label="Permalink to &quot;调试&quot;">​</a></h2><p>调试面板只对拥有 <code>code · debug</code> 权限的用户显示。它会按 Code 类型列出可调试资源，点击后打开调试标签页。</p>',6)),r(e,{src:"/product/developer-mode/debug-panel.png",alt:"开发者模式调试面板：可调试代码列表和调试标签",width:"1120"}),t[4]||(t[4]=d('<table tabindex="0"><thead><tr><th>区域</th><th>说明</th></tr></thead><tbody><tr><td>左侧调试列表</td><td>按 Code 类型分组，例如 API、CodeBlock、PageScript 等</td></tr><tr><td>调试标签页</td><td>打开当前调试会话，提供刷新和预览按钮</td></tr><tr><td>控制台输入</td><td>调试会话未结束时，可输入代码并回车执行</td></tr><tr><td>执行结果</td><td>控制台会把返回值以文本或 JSON 树展示</td></tr></tbody></table><p>这里的文档只说明后台入口和操作方式。具体可调试代码如何编写、上下文变量如何使用，请看 <a href="/kb-docs/zh/api/">API</a> 和 <a href="/kb-docs/zh/templateEngine/">模板引擎</a> 对应章节。</p><h2 id="常用工作流" tabindex="-1">常用工作流 <a class="header-anchor" href="#常用工作流" aria-label="Permalink to &quot;常用工作流&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目标</th><th>操作</th></tr></thead><tbody><tr><td>同时调整页面和布局</td><td>打开 <strong>页面</strong> 面板 → 打开页面 → 打开 <strong>布局</strong> 面板 → 打开对应布局 → 来回切换标签保存</td></tr><tr><td>修改外部 CSS 或 JS</td><td>打开 <strong>样式</strong> 或 <strong>脚本</strong> 面板 → 找到外部资源 → 修改 → 保存 → 预览</td></tr><tr><td>查找某段代码在哪里</td><td>打开 <strong>搜索</strong> 面板 → 输入关键字 → 需要精确匹配时打开 <code>Aa</code> 或 <code>.*</code> → 点击命中行</td></tr><tr><td>调试 API 或 CodeBlock</td><td>打开 <strong>调试</strong> 面板 → 点击代码资源 → 进入调试标签 → 需要时用控制台执行辅助表达式</td></tr><tr><td>让 AI 理解当前文件</td><td>打开资源标签 → 右键标签 → <strong>添加代码引用</strong> → 在 AI 全局聊天继续提问</td></tr></tbody></table><h2 id="与-cms-开发菜单的关系" tabindex="-1">与 CMS 开发菜单的关系 <a class="header-anchor" href="#与-cms-开发菜单的关系" aria-label="Permalink to &quot;与 CMS 开发菜单的关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>CMS 开发菜单</th><th>开发者模式</th></tr></thead><tbody><tr><td>适合创建、删除、批量管理和查看结构化列表</td><td>适合打开多个资源连续编辑</td></tr><tr><td>每类资源有独立页面和表单</td><td>页面、视图、布局、脚本、样式、Code 等在同一工作区中切换</td></tr><tr><td>文档按菜单逐页说明字段和按钮</td><td>本页说明统一工作台的使用方式</td></tr><tr><td>更适合实施人员按表单配置</td><td>更适合开发者按文件上下文排查和修改</td></tr></tbody></table><h2 id="退出前检查" tabindex="-1">退出前检查 <a class="header-anchor" href="#退出前检查" aria-label="Permalink to &quot;退出前检查&quot;">​</a></h2><p>离开开发者模式前，建议按顺序检查：</p><ol><li>顶部标签页是否还有小圆点。</li><li>需要保存的标签是否已经点过保存。</li><li>预览页面是否已经刷新确认。</li><li>如果要切换站点，先关闭或保存当前站点的标签页。</li></ol><p>如果仍有打开的标签，离开时会提示“离开当前网站的开发者模式将关闭所有文件选项卡。确认离开吗？”。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="/kb-docs/zh/cms/development/">CMS：开发</a></td><td>各类站点资源的后台列表和表单操作</td></tr><tr><td><a href="/kb-docs/zh/cms/site/pages.html">CMS：页面</a></td><td>页面列表、创建、编辑和设置</td></tr><tr><td><a href="/kb-docs/zh/templateEngine/">模板引擎</a></td><td>Page、Layout、View、Script、Style 的运行方式</td></tr><tr><td><a href="/kb-docs/zh/api/">API</a></td><td>KScript API 与 CodeBlock 等开发参考</td></tr><tr><td><a href="./ai-chat.html">AI Claw / AI Chat</a></td><td>与开发者模式配合使用的 AI 入口</td></tr></tbody></table>',12))])}const C=o(c,[["render",i]]);export{u as __pageData,C as default};
